catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }		
		var selected_room= g_form.getValue('room_location');		
   if ((selected_room =='Conference Center')){
	    g_form.clearValue('event_start_date','');
		g_form.clearValue('event_end_date');
		g_form.clearValue('event_title');
		g_form.clearValue('do_you_need_breakout_rooms');
		g_form.clearValue('number_of_onsite_attendees');
		if (selected_room =='Conference Center'){		
		g_form.setMandatory('number_of_onsite_attendees',true);	
		 }

		g_form.setMandatory('event_start_date',true);
        g_form.setMandatory('event_end_date',true);
        g_form.setMandatory('event_title',true);
		g_form.setMandatory('do_you_need_breakout_rooms',true);			 
   }

	else if (selected_room !='Conference Center'){
		g_form.setMandatory('event_start_date',false);
        g_form.setMandatory('event_end_date',false);
        g_form.setMandatory('event_title',false);
		g_form.setMandatory('do_you_need_breakout_rooms',false);
		g_form.setMandatory('number_of_onsite_attendees',false);		
		g_form.setMandatory('requested_room',false);
	}
}
